{
  "checks": [
    {
      "candidate_id": "node.68f8e39cf8e43c95a1e0890d",
      "claim_id": "claim.00add447f3aeed5d91c6f5c4",
      "source_support": {
        "status": "SUPPORTED",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u32.4805",
            "quote": "A Fund classified as a complex product will be subject to the SFC’s prevailing requirements for the sale of complex products8 including but not limited to ensuring the suitability of the Fund for its investors irrespective of whether solicitation or recommendation is involved."
          },
          {
            "unit_id": "d4148dd852cee.u65.9044",
            "quote": "Paragraph 5.5 of the SFC’s Code of Conduct for Persons Licensed by or Registered with the Securities and Futures Commission and Chapter 6 of the SFC’s Guidelines on Online Distribution and Advisory Platforms, and the relevant Frequently Asked Questions."
          }
        ],
        "rationale": "The circular expressly states the consequence of classification, including suitability without solicitation or recommendation. The precise regulated addressees and qualifications require the referenced authorities."
      },
      "question_relation": {
        "status": "NOT_APPLICABLE_TO_THIS_QUESTION",
        "question_hash": "4f10da87ddb322d03b098a5b1c69788f047e6978f5ae63ea518a5ed15a2de392",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u32.4805",
            "quote": "A Fund classified as a complex product will be subject to the SFC’s prevailing requirements for the sale of complex products8"
          }
        ],
        "rationale": "The question determines classification at an assessment time. Duties following classification are supported but do not determine either classification route."
      },
      "executable_correspondence": {
        "status": "NOT_APPLICABLE",
        "representation_quotes": [
          "Result: at least one of these conditions holds: [the fact aggregate_private_market_exposure_at_least_half_nav; the fact applicable_sfc_complex_product_designation]"
        ],
        "rationale": "The executable returns a classification result, not compliance with suitability or other sale requirements. Their absence is not a defect relative to this question."
      },
      "authority": {
        "status": "MISSING",
        "dependency_ids": [],
        "rationale": "The authorities identified in footnote 8 are not supplied. No mapping identifies which opaque missing dependency IDs correspond to them."
      },
      "followup_questions": [
        "Can the applicable versions of Code of Conduct paragraph 5.5, Chapter 6 of the Guidelines on Online Distribution and Advisory Platforms, and the relevant FAQs be supplied and mapped to dependency IDs before assessing downstream sale duties?"
      ]
    },
    {
      "candidate_id": "node.68f8e39cf8e43c95a1e0890d",
      "claim_id": "claim.01925f8d5a24687b8c662d14",
      "source_support": {
        "status": "SUPPORTED",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u61.8338",
            "quote": "CLOs are securities backed by a pool of debt, typically leveraged loans and broadly syndicated loans, or direct lending to unlisted companies."
          }
        ],
        "rationale": "The claim preserves the footnote’s descriptive definition and its non-exclusive word 'typically'."
      },
      "question_relation": {
        "status": "RELEVANT",
        "question_hash": "4f10da87ddb322d03b098a5b1c69788f047e6978f5ae63ea518a5ed15a2de392",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u1.5",
            "quote": "indirect exposures2 including through investments in business development companies (BDCs)3, collateralised loan obligations (CLOs)4 or financial derivative instruments5."
          }
        ],
        "rationale": "The definition informs identification of assets underlying the aggregate-exposure input. Holding a CLO is not itself an independent classification trigger."
      },
      "executable_correspondence": {
        "status": "OMITS",
        "representation_quotes": [
          "aggregate_private_market_exposure_at_least_half_nav: Whether established total direct and indirect exposure to private market assets amounts to at least 50% of the Fund's NAV at the assessment time. Supplying this fact requires resolving applicable exposure measurement and aggregation; missing holdings or measurement evidence is not false. (Boolean inclusive 50%-of-NAV threshold fact)",
          "Supplied classifications requiring judgment: listed_closed_ended_alternative_asset_fund, aggregate_private_market_exposure_at_least_half_nav, applicable_sfc_complex_product_designation. Their assessment is not implemented by this formula."
        ],
        "rationale": "No executable CLO definition or underlying-asset assessment is supplied. This is an expressly deferred input-classification step, not evidence that the Boolean classification formula contradicts the definition."
      },
      "authority": {
        "status": "NONE_DECLARED",
        "dependency_ids": [],
        "rationale": "The retained circular supplies the descriptive definition; no additional external dependency is necessary for this claim."
      },
      "followup_questions": [
        "What upstream process identifies relevant CLO holdings and their private-market exposure without treating every CLO as an automatic classification trigger?"
      ]
    },
    {
      "candidate_id": "node.68f8e39cf8e43c95a1e0890d",
      "claim_id": "claim.039ba8892a288957125a354e",
      "source_support": {
        "status": "SUPPORTED",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u21.3779",
            "quote": "A Fund will be considered as a complex product if its total direct and indirect exposures to private market assets amount to 50% or more of the Fund’s NAV."
          },
          {
            "unit_id": "d4148dd852cee.u63.8691",
            "quote": "Except for listed closed-ended alternative asset funds (LAFs)."
          }
        ],
        "rationale": "The threshold is inclusive and aggregates direct and indirect exposures. The footnote excludes LAFs from the covered Funds."
      },
      "question_relation": {
        "status": "RELEVANT",
        "question_hash": "4f10da87ddb322d03b098a5b1c69788f047e6978f5ae63ea518a5ed15a2de392",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u21.3779",
            "quote": "A Fund will be considered as a complex product if its total direct and indirect exposures to private market assets amount to 50% or more of the Fund’s NAV."
          }
        ],
        "rationale": "This is the automatic route directly tested by the question."
      },
      "executable_correspondence": {
        "status": "PRESERVES",
        "representation_quotes": [
          "Scope: all of these conditions hold: [the fact sfc_authorised_public_fund; it is not the case that [the fact listed_closed_ended_alternative_asset_fund]]",
          "Result: at least one of these conditions holds: [the fact aggregate_private_market_exposure_at_least_half_nav; the fact applicable_sfc_complex_product_designation]",
          "aggregate_private_market_exposure_at_least_half_nav: Whether established total direct and indirect exposure to private market assets amounts to at least 50% of the Fund's NAV at the assessment time. Supplying this fact requires resolving applicable exposure measurement and aggregation; missing holdings or measurement evidence is not false. (Boolean inclusive 50%-of-NAV threshold fact)"
        ],
        "rationale": "For a covered Fund, the inclusive aggregate-threshold fact is sufficient for TRUE. Preservation is conditional on the supplied measurement fact; the formula does not calculate exposure."
      },
      "authority": {
        "status": "NONE_DECLARED",
        "dependency_ids": [],
        "rationale": "The circular itself supplies the threshold rule. It does not identify an additional authority necessary to establish that rule."
      },
      "followup_questions": [
        "What valuation, aggregation and measurement-date evidence establishes the threshold fact for the particular Fund, including exactly 50% and temporary crossings?"
      ]
    },
    {
      "candidate_id": "node.68f8e39cf8e43c95a1e0890d",
      "claim_id": "claim.08e9a7a01c4bed6b0f450ed9",
      "source_support": {
        "status": "SUPPORTED",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u58.7778",
            "quote": "Direct investments in/exposures to private assets fall within the investment limit of 15% of a Fund’s total net asset value (NAV) under 7.3 of the Code on Unit Trusts and Mutual Funds (UT Code)."
          },
          {
            "unit_id": "d4148dd852cee.u21.3779",
            "quote": "A Fund will be considered as a complex product if its total direct and indirect exposures to private market assets amount to 50% or more of the Fund’s NAV."
          }
        ],
        "rationale": "The source distinguishes the referenced direct-investment limit from the aggregate classification threshold. It does not supply the full operation or qualifications of UT Code paragraph 7.3."
      },
      "question_relation": {
        "status": "NOT_APPLICABLE_TO_THIS_QUESTION",
        "question_hash": "4f10da87ddb322d03b098a5b1c69788f047e6978f5ae63ea518a5ed15a2de392",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u58.7778",
            "quote": "Direct investments in/exposures to private assets fall within the investment limit of 15% of a Fund’s total net asset value (NAV) under 7.3 of the Code on Unit Trusts and Mutual Funds (UT Code)."
          }
        ],
        "rationale": "Compliance with the separate investment limit is not a condition of either classification route. A breach would not justify excluding a Fund from classification."
      },
      "executable_correspondence": {
        "status": "NOT_APPLICABLE",
        "representation_quotes": [
          "Result: at least one of these conditions holds: [the fact aggregate_private_market_exposure_at_least_half_nav; the fact applicable_sfc_complex_product_designation]"
        ],
        "rationale": "The executable does not assess the 15% limit, appropriately for this classification question."
      },
      "authority": {
        "status": "MISSING",
        "dependency_ids": [],
        "rationale": "UT Code paragraph 7.3 is referenced but not supplied. The packet does not map it to an identifiable dependency ID."
      },
      "followup_questions": [
        "Can the applicable UT Code paragraph 7.3 and its relevant qualifications be supplied and mapped to a dependency ID if investment-limit compliance is to be assessed separately?"
      ]
    },
    {
      "candidate_id": "node.68f8e39cf8e43c95a1e0890d",
      "claim_id": "claim.10bac0eaa7311ec653c12f95",
      "source_support": {
        "status": "SUPPORTED",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u4.564",
            "quote": "This circular provides guidance to management companies of funds that are authorised by the SFC for offering to the public in Hong Kong (Funds)6 in this regard."
          },
          {
            "unit_id": "d4148dd852cee.u63.8691",
            "quote": "Except for listed closed-ended alternative asset funds (LAFs)."
          }
        ],
        "rationale": "The text establishes both the management-company addressee and the covered Fund population, subject to the express exclusion."
      },
      "question_relation": {
        "status": "RELEVANT",
        "question_hash": "4f10da87ddb322d03b098a5b1c69788f047e6978f5ae63ea518a5ed15a2de392",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u4.564",
            "quote": "funds that are authorised by the SFC for offering to the public in Hong Kong (Funds)6"
          },
          {
            "unit_id": "d4148dd852cee.u63.8691",
            "quote": "Except for listed closed-ended alternative asset funds (LAFs)."
          }
        ],
        "rationale": "These are the scope conditions of the exact Fund-classification question."
      },
      "executable_correspondence": {
        "status": "PRESERVES",
        "representation_quotes": [
          "Scope: all of these conditions hold: [the fact sfc_authorised_public_fund; it is not the case that [the fact listed_closed_ended_alternative_asset_fund]]",
          "sfc_authorised_public_fund: Whether the particular fund is authorised by the SFC for offering to the public in Hong Kong at the assessment time. (Boolean fund-scope fact)"
        ],
        "rationale": "The scope requires public-offer authorisation and excludes LAFs. The management-company addressee is question context, not an additional Fund-classification condition."
      },
      "authority": {
        "status": "NONE_DECLARED",
        "dependency_ids": [],
        "rationale": "The circular establishes this exclusion without requiring the separate LAF circular to restate it. Borderline LAF identification may require additional material."
      },
      "followup_questions": []
    },
    {
      "candidate_id": "node.68f8e39cf8e43c95a1e0890d",
      "claim_id": "claim.1f03023e3fe60300a933d2fb",
      "source_support": {
        "status": "SUPPORTED",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u1.5",
            "quote": "direct exposure through investments in bank or non-bank direct lending in the form of loans or equities to unlisted companies (direct exposure)"
          }
        ],
        "rationale": "The claim follows the source’s description and does not assert an exhaustive asset taxonomy."
      },
      "question_relation": {
        "status": "RELEVANT",
        "question_hash": "4f10da87ddb322d03b098a5b1c69788f047e6978f5ae63ea518a5ed15a2de392",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u21.3779",
            "quote": "its total direct and indirect exposures to private market assets"
          }
        ],
        "rationale": "Identification of direct exposure contributes to the threshold input."
      },
      "executable_correspondence": {
        "status": "OMITS",
        "representation_quotes": [
          "Supplied classifications requiring judgment: listed_closed_ended_alternative_asset_fund, aggregate_private_market_exposure_at_least_half_nav, applicable_sfc_complex_product_designation. Their assessment is not implemented by this formula."
        ],
        "rationale": "The representation accepts an aggregate Boolean and does not execute the source’s direct-exposure definition. This is a declared upstream assessment boundary, not a demonstrated incorrect classification."
      },
      "authority": {
        "status": "NONE_DECLARED",
        "dependency_ids": [],
        "rationale": "No additional external authority is needed for the descriptive claim supplied by the circular."
      },
      "followup_questions": [
        "How does the upstream exposure assessment incorporate the described direct lending, loans and equities to unlisted companies?"
      ]
    },
    {
      "candidate_id": "node.65050459a1ce3ffe5cff6887",
      "claim_id": "claim.d6041e80e26c5854ec3a1ea5",
      "source_support": {
        "status": "SUPPORTED",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u59.7979",
            "quote": "The examples of indirect exposures set out in paragraph 1 above are non-exhaustive, and subject to review and update by the SFC from time to time in view of market developments."
          }
        ],
        "rationale": "Footnote 2 expressly prevents treating the examples as a closed list and permits later review and updates."
      },
      "question_relation": {
        "status": "RELEVANT",
        "question_hash": "081eed6b6dc4b643c2ba1dc9591087fbcfed74b457b2c0bb6762b340bf15cd25",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u59.7979",
            "quote": "The examples of indirect exposures set out in paragraph 1 above are non-exhaustive"
          }
        ],
        "rationale": "An exhaustive example-based filter could understate the aggregate exposure used by this classification question."
      },
      "executable_correspondence": {
        "status": "OMITS",
        "representation_quotes": [
          "aggregate_exposure_at_least_half_nav: Whether the Fund's total direct and indirect exposure to private market assets amounts to at least 50% of its NAV at the assessment time, using the applicable methodology. Missing or unresolved measurement evidence leaves this fact unknown. (Boolean)",
          "Supplied classifications requiring judgment: is_laf, aggregate_exposure_at_least_half_nav, operative_sfc_designation. Their assessment is not implemented by this formula."
        ],
        "rationale": "The executable contains no closed list, so no restrictive conflict is established. It also contains no executable process for recognising additional exposure types or incorporating updates; that work is deferred to the supplied aggregate fact."
      },
      "authority": {
        "status": "NONE_DECLARED",
        "dependency_ids": [],
        "rationale": "The retained footnote establishes the open-ended treatment. The packet establishes neither the existence nor the content of a subsequent update."
      },
      "followup_questions": [
        "Does the upstream assessment allow indirect exposures beyond the listed examples, and is any subsequent SFC update applicable at the selected assessment time?"
      ]
    },
    {
      "candidate_id": "node.65050459a1ce3ffe5cff6887",
      "claim_id": "claim.e10a40045eb85f553f5f786d",
      "source_support": {
        "status": "SUPPORTED",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u4.564",
            "quote": "This circular provides guidance to management companies of funds that are authorised by the SFC for offering to the public in Hong Kong (Funds)6 in this regard."
          },
          {
            "unit_id": "d4148dd852cee.u63.8691",
            "quote": "Except for listed closed-ended alternative asset funds (LAFs)."
          }
        ],
        "rationale": "The main text and footnote jointly support the claimed scope and addressees."
      },
      "question_relation": {
        "status": "RELEVANT",
        "question_hash": "081eed6b6dc4b643c2ba1dc9591087fbcfed74b457b2c0bb6762b340bf15cd25",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u4.564",
            "quote": "funds that are authorised by the SFC for offering to the public in Hong Kong (Funds)6"
          },
          {
            "unit_id": "d4148dd852cee.u63.8691",
            "quote": "Except for listed closed-ended alternative asset funds (LAFs)."
          }
        ],
        "rationale": "The question expressly concerns this covered Fund population at an assessment time."
      },
      "executable_correspondence": {
        "status": "PRESERVES",
        "representation_quotes": [
          "Scope: all of these conditions hold: [the fact public_sfc_authorised; it is not the case that [the fact is_laf]]",
          "public_sfc_authorised: Whether the assessed fund is authorised by the SFC for offering to the public in Hong Kong at the assessment time. (Boolean)",
          "is_laf: Whether the assessed fund is a listed closed-ended alternative asset fund within the footnote 6 exclusion. (Boolean)"
        ],
        "rationale": "The executable matches both scope conditions. It does not turn excluded Funds into negative classification findings."
      },
      "authority": {
        "status": "NONE_DECLARED",
        "dependency_ids": [],
        "rationale": "The exclusion and public-authorisation scope are supplied directly. Separate LAF rules are unnecessary to establish this circular’s exclusion."
      },
      "followup_questions": []
    },
    {
      "candidate_id": "node.65050459a1ce3ffe5cff6887",
      "claim_id": "claim.e22078cd8ec31b01b23ac005",
      "source_support": {
        "status": "SUPPORTED",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u21.3779",
            "quote": "On a case-by-case basis, the SFC may also designate a Fund as a complex product, taking into account factors including, without limitation:"
          },
          {
            "unit_id": "d4148dd852cee.u29.4630",
            "quote": "In assessing whether the complex product designation is warranted7, the SFC will adopt a holistic approach taking into account the specific circumstances of the case."
          },
          {
            "unit_id": "d4148dd852cee.u64.8910",
            "quote": "In cases where the Fund’s aggregate direct and indirect exposures to private market assets are less than 50% of the Fund’s NAV."
          }
        ],
        "rationale": "The SFC has discretionary designation power using non-exhaustive, holistic considerations. Footnote 7 locates the warranted-designation assessment below 50%; at or above 50%, classification already follows automatically."
      },
      "question_relation": {
        "status": "RELEVANT",
        "question_hash": "081eed6b6dc4b643c2ba1dc9591087fbcfed74b457b2c0bb6762b340bf15cd25",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u21.3779",
            "quote": "On a case-by-case basis, the SFC may also designate a Fund as a complex product"
          }
        ],
        "rationale": "An actual applicable designation supplies the question’s alternative classification route. The question does not ask the formula to exercise SFC discretion."
      },
      "executable_correspondence": {
        "status": "PRESERVES",
        "representation_quotes": [
          "Result: at least one of these conditions holds: [the fact aggregate_exposure_at_least_half_nav; the fact operative_sfc_designation]",
          "operative_sfc_designation: Whether an SFC case-by-case designation of this Fund as a complex product under this circular is operative at the assessment time. Mere designation risk or missing records does not establish either truth value. (Boolean)"
        ],
        "rationale": "The executable recognises an actual operative designation without making risk factors automatic triggers. Its unconditional OR does not change known-threshold classification outcomes: at or above 50% the automatic route already suffices. It does not implement the designation decision or establish its temporal persistence."
      },
      "authority": {
        "status": "NONE_DECLARED",
        "dependency_ids": [],
        "rationale": "The circular supplies the discretionary power. A Fund-specific decision is necessary evidence to populate the designation fact, but no such decision is identified or supplied."
      },
      "followup_questions": [
        "What Fund-specific SFC decision, including its effective terms and any withdrawal or variation, establishes whether a designation is operative at the assessment time?",
        "If exposure has changed since designation, what decision terms or applicable authority determine persistence of the designation?"
      ]
    },
    {
      "candidate_id": "node.65050459a1ce3ffe5cff6887",
      "claim_id": "claim.e7c324d6e9dd986d9a0955a1",
      "source_support": {
        "status": "SUPPORTED",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u21.3779",
            "quote": "taking into account factors including, without limitation:"
          },
          {
            "unit_id": "d4148dd852cee.u28.4505",
            "quote": "any distribution restrictions, requirements or other conditions as may be imposed by the Fund’s home regulators."
          },
          {
            "unit_id": "d4148dd852cee.u29.4630",
            "quote": "the SFC will adopt a holistic approach taking into account the specific circumstances of the case."
          }
        ],
        "rationale": "Home-regulator conditions are expressly included among non-exhaustive considerations, not stated as independently sufficient triggers."
      },
      "question_relation": {
        "status": "NOT_APPLICABLE_TO_THIS_QUESTION",
        "question_hash": "081eed6b6dc4b643c2ba1dc9591087fbcfed74b457b2c0bb6762b340bf15cd25",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u29.4630",
            "quote": "In assessing whether the complex product designation is warranted7"
          },
          {
            "unit_id": "d4148dd852cee.u28.4505",
            "quote": "any distribution restrictions, requirements or other conditions as may be imposed by the Fund’s home regulators."
          }
        ],
        "rationale": "These considerations inform whether the SFC should designate. The exact question tests an existing operative designation, not whether designation is warranted. They remain relevant context but are not additional executable conditions."
      },
      "executable_correspondence": {
        "status": "NOT_APPLICABLE",
        "representation_quotes": [
          "operative_sfc_designation: Whether an SFC case-by-case designation of this Fund as a complex product under this circular is operative at the assessment time. Mere designation risk or missing records does not establish either truth value. (Boolean)"
        ],
        "rationale": "The formula does not reproduce the SFC’s discretionary assessment. Adding home-regulator restrictions as automatic triggers would exceed the supplied rule."
      },
      "authority": {
        "status": "NONE_DECLARED",
        "dependency_ids": [],
        "rationale": "The circular suffices to establish that these conditions are relevant factors. No particular home-regulator instrument is identified whose content must be verified for this generic claim."
      },
      "followup_questions": [
        "If the intended task expands to whether designation is warranted, which Fund-specific home-regulator restrictions and underlying instruments apply?"
      ]
    },
    {
      "candidate_id": "node.65050459a1ce3ffe5cff6887",
      "claim_id": "claim.e97a5ab05dba08850901077d",
      "source_support": {
        "status": "SUPPORTED",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u49.6955",
            "quote": "Fund managers are encouraged to consult the SFC at the earliest opportunity if they are in doubt regarding complex product classification of their Funds."
          }
        ],
        "rationale": "The statement accurately preserves encouragement and its timing. The extraction’s OBLIGATION label must not be interpreted as a mandatory consultation requirement."
