      "question_relation": {
        "status": "NOT_APPLICABLE_TO_THIS_QUESTION",
        "question_hash": "081eed6b6dc4b643c2ba1dc9591087fbcfed74b457b2c0bb6762b340bf15cd25",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u49.6955",
            "quote": "Fund managers are encouraged to consult the SFC at the earliest opportunity if they are in doubt regarding complex product classification of their Funds."
          }
        ],
        "rationale": "Consultation is recommended conduct in response to doubt, not a classification trigger, a prerequisite to classification, or a default answer while evidence is missing."
      },
      "executable_correspondence": {
        "status": "NOT_APPLICABLE",
        "representation_quotes": [
          "Missing or temporally unavailable facts evaluate as UNKNOWN."
        ],
        "rationale": "The question does not assess consultation conduct. Preserving UNKNOWN neither implements the recommendation nor conflicts with it."
      },
      "authority": {
        "status": "NONE_DECLARED",
        "dependency_ids": [],
        "rationale": "The circular itself supplies the recommendation; no additional external dependency is needed."
      },
      "followup_questions": []
    },
    {
      "candidate_id": "node.65050459a1ce3ffe5cff6887",
      "claim_id": "claim.f8f22b0f0f1f77228e7e9fda",
      "source_support": {
        "status": "SUPPORTED",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u21.3779",
            "quote": "A Fund will be considered as a complex product if its total direct and indirect exposures to private market assets amount to 50% or more of the Fund’s NAV."
          },
          {
            "unit_id": "d4148dd852cee.u63.8691",
            "quote": "Except for listed closed-ended alternative asset funds (LAFs)."
          }
        ],
        "rationale": "The whole-source reading supports mandatory classification at an inclusive aggregate 50% threshold for covered non-LAF Funds."
      },
      "question_relation": {
        "status": "RELEVANT",
        "question_hash": "081eed6b6dc4b643c2ba1dc9591087fbcfed74b457b2c0bb6762b340bf15cd25",
